vector<long long> partial[MAXN], partial_zero[MAXN];

void compute_comb() {
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

long long get_difs(int conf, int a_bef, int b_bef) {
    long long total = 0;
    for (int i = 0; i <= c; ++i) {
        if (conf & (1 << i)) {
            b_bef++;
            long long aux1 = comb[b_bef - 1][r - 1];
            long long aux2 = comb[n - b_bef][r] - comb[a_bef][r];
            total -= aux1 * aux2;
        } else {
            a_bef++;
            long long aux1 = comb[a_bef - 1][r - 1];
            long long aux2 = comb[n - a_bef][r] - comb[b_bef][r];
            total += aux1 * aux2;
        }
    }
    return total;
}

bool check_conf(int conf) {
