    int limit = 1 << (c + 1);
    for (int conf = 0; conf < limit; ++conf) {
        int b_here = __builtin_popcount(conf);
        int a_here = c + 1 - b_here;
        if (check_conf(conf))
            partial[a_here].push_back(get_difs(conf, r + c - a_here, r + c - b_here));
        else
            partial_zero[a_here].push_back(get_difs(conf, r + c - a_here, r + c - b_here));
    }
    for (int i = 0; i <= c + 1; ++i) {
        sort(partial[i].begin(), partial[i].end());
        sort(partial_zero[i].begin(), partial_zero[i].end());
    }
}

long long get_coef(int conf) {
    int i;
    for (i = 0; i <= c; ++i) {
        if ( ((conf >> i) & 1) != (conf & 1) ) break;
    }
    for (int j = i; j <= c; ++j) {
        if (s[2 * r - 1 + j] == 'A' && (((conf >> j) & 1) == 1)) return 0;
        if (s[2 * r - 1 + j] == 'B' && (((conf >> j) & 1) == 0)) return 0;
    }
    int set_a = r - 1 + ( (conf & 1) == 0 ? i : 0 );
    int set_b = r - 1 + ( (conf & 1) == 1 ? i : 0 );
    if (set_a < cnt_a[2 * r - 2 + i]) return 0;
    if (set_b < cnt_b[2 * r - 2 + i]) return 0;
    int total = set_a + set_b - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i];
    return comb[total][set_a - cnt_a[2 * r - 2 + i]];
}

void update_pair(pair<long long, long long>& ans, pair<long long, long long> act) {
    if (act.first < 0) act.first = -act.first;
    if (ans.first > act.first) {
        ans = act;
    } else if (ans.first == act.first) {
        ans.second += act.second;
    }
