                update_pair(answer, {abs(val), coef * count_coef});
            }
        }
        if (it != partial[c + 1 - a_here].begin()) {
            --it;
            long long val = *it + act;
            if (abs(val) <= answer.first) {
                long long count_coef = count_in_vector(partial[c + 1 - a_here], *it);
                update_pair(answer, {abs(val), coef * count_coef});
