public class Main {
    static final int MAXN = 66;
    static int r, c, n;
    static String s;
    static long[][] comb = new long[MAXN][MAXN];
    static int[] cnt_a = new int[MAXN], cnt_b = new int[MAXN];
    static List<Long>[] partial = new ArrayList[MAXN], partial_zero = new ArrayList[MAXN];

    static {
        for (int i = 0; i < MAXN; i++) {
            partial[i] = new ArrayList<>();
            partial_zero[i] = new ArrayList<>();
        }
    }

    static void compute_comb() {
        for (int i = 0; i <= n; ++i) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; ++j)
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }

    static long get_difs(int conf, int a_bef, int b_bef) {
        long total = 0;
        for (int i = 0; i <= c; ++i) {
            if ((conf & (1 << i)) != 0) {
                b_bef++;
                long aux1 = comb[b_bef - 1][r - 1];
                long aux2 = comb[n - b_bef][r] - comb[a_bef][r];
                total -= aux1 * aux2;
            } else {
                a_bef++;
                long aux1 = comb[a_bef - 1][r - 1];
                long aux2 = comb[n - a_bef][r] - comb[b_bef][r];
                total += aux1 * aux2;
            }
        }
        return total;
    }

    static boolean check_conf(int conf) {
        for (int i = 0; i <= c; ++i) {
            char ch = s.charAt(2 * r + c + i);
            if (ch == 'A' && ((conf >> i) & 1) == 1) return false;
            if (ch == 'B' && ((conf >> i) & 1) == 0) return false;
        }
        return true;
    }

    static void compute_second_part() {
        int limit = 1 << (c + 1);
        for (int conf = 0; conf < limit; ++conf) {
            int b_here = Integer.bitCount(conf);
            int a_here = c + 1 - b_here;
            if (check_conf(conf))
                partial[a_here].add(get_difs(conf, r + c - a_here, r + c - b_here));
            else
                partial_zero[a_here].add(get_difs(conf, r + c - a_here, r + c - b_here));
        }
        for (int i = 0; i <= c + 1; ++i) {
            Collections.sort(partial[i]);
            Collections.sort(partial_zero[i]);
        }
    }

    static long get_coef(int conf) {
        int i;
        for (i = 0; i <= c; ++i) {
            if ( (((conf >> i) & 1) != (conf & 1)) ) break;
        }
        for (int j = i; j <= c; ++j) {
            char ch = s.charAt(2 * r - 1 + j);
            if (ch == 'A' && (((conf >> j) & 1) == 1)) return 0;
