        int set_a = r - 1 + ( ((conf & 1) == 0) ? i : 0 );
        int set_b = r - 1 + ( ((conf & 1) == 1) ? i : 0 );
        if (set_a < cnt_a[2 * r - 2 + i]) return 0;
        if (set_b < cnt_b[2 * r - 2 + i]) return 0;
        int total = set_a + set_b - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i];
        return comb[total][set_a - cnt_a[2 * r - 2 + i]];
    }

    static class Pair {
        long first, second;
        Pair(long f, long s) {
            this.first = f;
            this.second = s;
        }
    }

    static void update_pair(Pair ans, Pair act) {
        if (act.first < 0) act.first = -act.first;
        if (ans.first > act.first) {
            ans.first = act.first;
            ans.second = act.second;
        } else if (ans.first == act.first) {
            ans.second += act.second;
