        if (lower < 0) lower = -lower - 1;
        int upper = Collections.binarySearch(data, val + 1);
        if (upper < 0) upper = -upper - 1;
        return upper - lower;
    }

    static long compute_first_part() {
        int limit = 1 << (c + 1);
        Pair answer = new Pair(1L << 60, 0);
