            int idx_zero = Collections.binarySearch(partial_zero[c + 1 - a_here], -act);
            if (idx_zero >= 0) {
                long val = partial_zero[c + 1 - a_here].get(idx_zero) + act;
                long count_coef = count_in_vector(partial[c + 1 - a_here], partial_zero[c + 1 - a_here].get(idx_zero));
                if (Math.abs(val) <= answer.first) {
